import React from 'react';

export type ModalProps = {
  open: boolean;
  title: string;
  children: React.ReactNode;
  confirmLabel?: string;
  onConfirm?: () => void;
  onClose: () => void;
};

// The app's only dialog. Every confirmation and form popup goes through it.
export function Modal({ open, title, children, confirmLabel, onConfirm, onClose }: ModalProps) {
  if (!open) return null;
  return (
    <div role="dialog" aria-modal="true" className="modal">
      <h2>{title}</h2>
      {children}
      <button onClick={onClose}>Cancel</button>
      {onConfirm && <button onClick={onConfirm}>{confirmLabel ?? 'OK'}</button>}
    </div>
  );
}

